DROP PROCEDURE IF EXISTS add_migration;
delimiter ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20260728140000');
IF v=0 THEN
INSERT INTO `migrations` VALUES ('20260728140000');

SET @MARKET_STALL_EVENT := 153;

DELETE FROM `game_event_creature` WHERE `event`=@MARKET_STALL_EVENT;
DELETE FROM `game_event_gameobject` WHERE `event`=@MARKET_STALL_EVENT;
DELETE FROM `game_event` WHERE `entry`=@MARKET_STALL_EVENT;
